/**
 * Google Drive Node - Version 1
 * Discriminator: resource=drive, operation=list
 */


interface Credentials {
  googleApi: CredentialReference;
  googleDriveOAuth2Api: CredentialReference;
}

/** List files and folders */
export type GoogleDriveV1DriveListParams = {
  resource: 'drive';
  operation: 'list';
/**
 * Authentication
 * @default serviceAccount
 */
    authentication?: 'serviceAccount' | 'oAuth2' | Expression<string>;
/**
 * Options
 * @default {}
 */
    options?: {
    /** The fields to return
     * @default []
     */
    fields?: Array<'*' | 'explicitlyTrashed' | 'exportLinks' | 'hasThumbnail' | 'iconLink' | 'id' | 'kind' | 'mimeType' | 'name' | 'permissions' | 'shared' | 'spaces' | 'starred' | 'thumbnailLink' | 'trashed' | 'version' | 'webViewLink'>;
    /** Query string for searching shared drives. See the &lt;a href="https://developers.google.com/drive/api/v3/search-shareddrives"&gt;"Search for shared drives"&lt;/a&gt; guide for supported syntax.
     */
    q?: string | Expression<string>;
  };
/**
 * Whether to return all results or only up to a given limit
 * @default false
 */
    returnAll?: boolean | Expression<boolean>;
/**
 * Max number of results to return
 * @displayOptions.show { returnAll: [false] }
 * @default 100
 */
    limit?: number | Expression<number>;
};

export type GoogleDriveV1DriveListNode = {
  type: 'n8n-nodes-base.googleDrive';
  version: 1;
  config: NodeConfig<GoogleDriveV1DriveListParams> & { credentials?: Credentials };
};